"""
転倒数 (Inversion Number / 反転数)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
数列 a において i < j かつ a[i] > a[j] を満たすペア (i, j) の総数。
バブルソートの交換回数に一致。
内部で座標圧縮を行うため、負の数や大きな値 (10^9 以上) を含む数列でもそのまま計算可能。

【引数・戻り値】
- inversion_num(a): 数列 a の転倒数を返す。O(N log N)。
"""

# https://github.com/ddfkit/acsampl/blob/main/tentou.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def inversion_num(a):
    vals=sorted(set(a));mp={v:i+1 for i,v in enumerate(vals)}
    n=len(vals);bit=[0]*(n+1);ans=0
    for i,x in enumerate(a):
        p=mp[x];s=0;r=p
        while r>0:s+=bit[r];r-=r&-r
        ans+=i-s;idx=p
        while idx<=n:bit[idx]+=1;idx+=idx&-idx
    return ans

if __name__ == "__main__":
    assert inversion_num([3, 1, 2]) == 2
    assert inversion_num([1, 2, 3, 4]) == 0
    assert inversion_num([4, 3, 2, 1]) == 6
    assert inversion_num([10**9, -5, 10**9, 0]) == 3
    print("tentou.py: tests passed!")